.chain-actions{display:flex;align-items:flex-end;gap:.35rem}.chain-actions label{display:flex;flex-direction:column;gap:.2rem}.chain-actions label>span{color:#7d8797;font-size:.65rem;font-weight:700}.chain-actions :deep(.p-datepicker){width:145px}.chain-actions :deep(.p-inputtext){padding:.4rem .5rem;font-size:.78rem}@media(max-width:1050px){.chain-panel>header{align-items:flex-start;flex-direction:column}.chain-actions{width:100%;flex-wrap:wrap}}
</style>
